import{_ as e,c as l,o as a,ag as t}from"./chunks/framework.D2yTFDqz.js";const p=JSON.parse('{"title":"2025.1.1","description":"","frontmatter":{"title":"2025.1.1"},"headers":[],"relativePath":"changelog/2025.1.1.md","filePath":"changelog/2025.1.1.md","lastUpdated":1737444893000}'),r={name:"changelog/2025.1.1.md"};function n(o,i,h,s,u,d){return a(),l("div",null,[...i[0]||(i[0]=[t('<h1 id="🎉-view-shadcn-ui-v2025-1-1-发布公告-强大的数据表格组件震撼来袭" tabindex="-1">🎉 View Shadcn UI v2025.1.1 发布公告：强大的数据表格组件震撼来袭！ <a class="header-anchor" href="#🎉-view-shadcn-ui-v2025-1-1-发布公告-强大的数据表格组件震撼来袭" aria-label="Permalink to &quot;🎉 View Shadcn UI v2025.1.1 发布公告：强大的数据表格组件震撼来袭！&quot;">​</a></h1><p>亲爱的开发者们：</p><p>我们很高兴地宣布 View Shadcn UI v2025.1.1 版本正式发布！本次更新的重点是全新的数据表格组件，它具备了企业级应用所需的众多特性，同时我们也修复了一些已知问题。</p><h2 id="🚀-重要链接" tabindex="-1">🚀 重要链接 <a class="header-anchor" href="#🚀-重要链接" aria-label="Permalink to &quot;🚀 重要链接&quot;">​</a></h2><ul><li>GitHub 仓库：<a href="https://github.com/devlive-community/view-shadcn-ui" target="_blank" rel="noreferrer">https://github.com/devlive-community/view-shadcn-ui</a></li><li>官方文档：<a href="https://view-shadcn-ui.devlive.org/" target="_blank" rel="noreferrer">https://view-shadcn-ui.devlive.org/</a></li><li>在线演练场：<a href="https://playground.view-shadcn-ui.devlive.org/" target="_blank" rel="noreferrer">https://playground.view-shadcn-ui.devlive.org/</a></li></ul><h2 id="📦-新版本亮点" tabindex="-1">📦 新版本亮点 <a class="header-anchor" href="#📦-新版本亮点" aria-label="Permalink to &quot;📦 新版本亮点&quot;">​</a></h2><h3 id="📊-全新数据表格组件" tabindex="-1">📊 全新数据表格组件 <a class="header-anchor" href="#📊-全新数据表格组件" aria-label="Permalink to &quot;📊 全新数据表格组件&quot;">​</a></h3><br><p>这是一个功能丰富的企业级表格组件，具备以下特性：</p><br><p><strong>核心功能</strong></p><ul><li>支持同步和异步分页</li><li>灵活的列排序功能</li><li>行选择（单选/多选）功能</li><li>单元格编辑能力</li><li>自定义右键菜单</li></ul><p><strong>交互增强</strong></p><ul><li>拖拽调整列宽</li><li>支持列位置移动</li><li>单元格点击事件</li><li>内容自动省略和提示</li><li>自定义列宽设置</li></ul><p><strong>使用体验</strong></p><ul><li>支持表格尺寸配置</li><li>可设置表格宽度和高度</li><li>加载状态展示</li><li>空数据提示</li><li>完整的单元格提示</li></ul><p><strong>高级特性</strong></p><ul><li>自定义单元格编辑器</li><li>自定义右键菜单内容</li><li>独立的提示 hook 封装</li></ul><h3 id="🐛-问题修复" tabindex="-1">🐛 问题修复 <a class="header-anchor" href="#🐛-问题修复" aria-label="Permalink to &quot;🐛 问题修复&quot;">​</a></h3><ul><li>修复按钮组件圆形显示混乱的问题</li><li>修复输入框未设置 name 字段导致的控制台警告</li><li>修复数字输入框在表单验证时的问题</li><li>修复表格编辑状态下的行选择问题</li><li>修复表格行多选状态同步问题</li><li>优化表格外部点击取消选择的逻辑</li></ul><h2 id="🔜-后续规划" tabindex="-1">🔜 后续规划 <a class="header-anchor" href="#🔜-后续规划" aria-label="Permalink to &quot;🔜 后续规划&quot;">​</a></h2><p>我们将持续优化数据表格组件的性能和功能，并计划添加更多企业级应用常用的特性。同时，我们也在积极开发其他新组件，敬请期待！</p><h2 id="🤝-参与贡献" tabindex="-1">🤝 参与贡献 <a class="header-anchor" href="#🤝-参与贡献" aria-label="Permalink to &quot;🤝 参与贡献&quot;">​</a></h2><p>如果您在使用过程中遇到问题或有新的想法，欢迎：</p><ul><li>提交 Issue：<a href="https://github.com/devlive-community/view-shadcn-ui/issues" target="_blank" rel="noreferrer">https://github.com/devlive-community/view-shadcn-ui/issues</a></li><li>贡献代码：<a href="https://github.com/devlive-community/view-shadcn-ui/pulls" target="_blank" rel="noreferrer">https://github.com/devlive-community/view-shadcn-ui/pulls</a></li></ul><p>特别感谢所有为这个版本贡献代码和反馈的开发者们！</p>',26)])])}const v=e(r,[["render",n]]);export{p as __pageData,v as default};
